module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // State mapping:
    // state[0] = S
    // state[1] = S1
    // state[2] = S11
    // state[3] = S110
    // state[4] = B0
    // state[5] = B1
    // state[6] = B2
    // state[7] = B3
    // state[8] = Count
    // state[9] = Wait

    assign S_next     = ((state[0] | state[1] | state[3]) & ~d) | (state[9] & ack);
    assign S1_next    = state[0] & d;
    assign B3_next    = state[6];
    assign Count_next = state[7];
    assign Wait_next  = state[8] & done_counting;

    assign shift_ena  = state[4] | state[5] | state[6] | state[7];
    assign counting   = state[8];
    assign done       = state[9];

endmodule

