module tb_TopModule;
    reg d;
    reg done_counting;
    reg ack;
    reg [9:0] state;

    wire B3_next;
    wire S_next;
    wire S1_next;
    wire Count_next;
    wire Wait_next;
    wire done;
    wire counting;
    wire shift_ena;

    TopModule dut (
        .d(d),
        .done_counting(done_counting),
        .ack(ack),
        .state(state),
        .B3_next(B3_next),
        .S_next(S_next),
        .S1_next(S1_next),
        .Count_next(Count_next),
        .Wait_next(Wait_next),
        .done(done),
        .counting(counting),
        .shift_ena(shift_ena)
    );

    initial begin
        // Test all states and input combinations
        // S (state[0] = 10'b0000000001)
        state = 10'b0000000001;
        d = 0; done_counting = 0; ack = 0; #1;
        if (S_next !== 1 || S1_next !== 0 || shift_ena !== 0 || counting !== 0 || done !== 0) begin
            $display("FAIL: S state with d=0"); $finish;
        end

        d = 1; #1;
        if (S1_next !== 1 || S_next !== 0) begin
            $display("FAIL: S state with d=1"); $finish;
        end

        // S1 (state[1] = 10'b0000000010)
        state = 10'b0000000010;
        d = 0; #1;
        if (S_next !== 1) begin
            $display("FAIL: S1 state with d=0"); $finish;
        end
        d = 1; #1;
        // S1 with d=1 goes to S11 (state[2]), so S_next=0, S1_next=0
        if (S_next !== 0 || S1_next !== 0) begin
            $display("FAIL: S1 state with d=1"); $finish;
        end

        // S11 (state[2] = 10'b0000000100)
        state = 10'b0000000100;
        d = 0; #1; // goes to S110
        d = 1; #1; // goes to S11

        // S110 (state[3] = 10'b0000001000)
        state = 10'b0000001000;
        d = 0; #1;
        if (S_next !== 1) begin
            $display("FAIL: S110 state with d=0"); $finish;
        end
        d = 1; #1; // goes to B0 (state[4])

        // B0 (state[4] = 10'b0000010000)
        state = 10'b0000010000;
        #1;
        if (shift_ena !== 1) begin
            $display("FAIL: B0 shift_ena"); $finish;
        end

        // B1 (state[5] = 10'b0000100000)
        state = 10'b0000100000;
        #1;
        if (shift_ena !== 1) begin
            $display("FAIL: B1 shift_ena"); $finish;
        end

        // B2 (state[6] = 10'b0001000000)
        state = 10'b0001000000;
        #1;
        if (shift_ena !== 1 || B3_next !== 1) begin
            $display("FAIL: B2 B3_next/shift_ena"); $finish;
        end

        // B3 (state[7] = 10'b0010000000)
        state = 10'b0010000000;
        #1;
        if (shift_ena !== 1 || Count_next !== 1) begin
            $display("FAIL: B3 Count_next/shift_ena"); $finish;
        end

        // Count (state[8] = 10'b0100000000)
        state = 10'b0100000000;
        done_counting = 0; #1;
        if (counting !== 1 || Wait_next !== 0) begin
            $display("FAIL: Count done_counting=0"); $finish;
        end
        done_counting = 1; #1;
        if (counting !== 1 || Wait_next !== 1) begin
            $display("FAIL: Count done_counting=1"); $finish;
        end

        // Wait (state[9] = 10'b1000000000)
        state = 10'b1000000000;
        ack = 0; #1;
        if (done !== 1 || S_next !== 0) begin
            $display("FAIL: Wait ack=0"); $finish;
        end
        ack = 1; #1;
        if (done !== 1 || S_next !== 1) begin
            $display("FAIL: Wait ack=1"); $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
